    """graph: {node: [neighbors]}. Returns the node list of a shortest path, or None."""
    if start == goal:
        return [start]
    prev = {start: None}
    q = deque([start])
    while q:
        u = q.popleft()
        for v in graph.get(u, ()):
            if v in prev:
                continue
            prev[v] = u
            if v == goal:
                path = [v]
                while prev[path[-1]] is not None:
                    path.append(prev[path[-1]])
                return path[::-1]
            q.append(v)
    return None

