def binary_search(xs: list[int], target: int) -> int:
    lo, hi = 0, len(xs) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if xs[mid] == target:
            return mid
        if xs[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

# Invariant: the answer, if present, always lies in the inclusive range [lo, hi]. Each iteration halves the range, giving O(log n) time and O(1) space. Requires a sorted input.

