def longest_unique_substring(s: str) -> int:
    last = {}
    start = best = 0
    for i, ch in enumerate(s):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = i
        best = max(best, i - start + 1)
    return best

# Sliding window with last-seen indices. Time: O(n), Space: O(min(n, alphabet)).

